static void decode_stop(Stop*s,const char*prefix,unsigned i){char p[128];path(p,prefix,i,"id");text(p,s->id,sizeof s->id);path(p,prefix,i,"name");text(p,s->name,sizeof s->name);path(p,prefix,i,"country");text(p,s->area,sizeof s->area);fold_latin(s->name);fold_latin(s->area);}
