static void received(int32_t status,const char*json,uint32_t size,void*u){(void)u;busy=0;if(closing||request_generation!=generation)return;uint32_t now=svc->monotonic_ms();if(status==200&&parse(json,size)){notice[0]=0;backoff=60000;refresh_at=now+120000;if(request_kind==0){last_refresh=now;board_valid=1;board_stop=selected;board_error[0]=0;}next_request=now+2000;}else{cp(notice,status==429?tr("Transitous rate limit","Transitous-Anfragelimit"):status==200?tr("Invalid transit response","Ungueltige Verkehrsdaten"):tr("Offline / request failed; cached times","Offline / Anfrage fehlgeschlagen; Cache"),sizeof notice);if(request_kind==0)cp(board_error,notice,sizeof board_error);uint32_t delay=svc->http_retry_seconds();if(delay>900)delay=900;delay*=1000;if(delay<backoff)delay=backoff;next_request=refresh_at=now+delay;if(backoff<900000)backoff=backoff>450000?900000:backoff*2;}dirty=1;}
